import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p37_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_swish_bias_groupnorm(
    torch::Tensor input,
    torch::Tensor bias,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups,
    float eps
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_swish_bias_groupnorm", &fused_swish_bias_groupnorm,
          "Fused Swish + bias add + GroupNorm (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffffu, val, offset);
    return val;
}

// One block per (sample, group): blockIdx.x=sample, blockIdx.y=group
// blockDim.x = group_size = C / num_groups (assumed == 64)
__global__ void __launch_bounds__(64, 4) fused_swish_bias_groupnorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int N, int C, float eps
) {
    const int sample   = blockIdx.x;
    const int group    = blockIdx.y;
    const int group_sz = blockDim.x;// 64
    const int tid      = threadIdx.x;
    const int chan     = group * group_sz + tid;

    // 1. Load GEMM output, apply Swish (x * sigmoid(x)), add bias
    float v = input[sample * C + chan];
    float pre_norm = v * (1.0f / (1.0f + __expf(-v))) + bias[chan];

    // Shared: [0]=warp0partial, [1]=warp1 partial, [2]=mean, [3]=inv_std
    __shared__ float smem[4];

    int warp_id = tid >> 5;
    int lane_id = tid & 31;

    //2. Mean: two-warp reduction
    float sum = warp_reduce_sum(pre_norm);
    if (lane_id == 0) smem[warp_id] = sum;
    __syncthreads();

    if (tid == 0) {
        smem[2] = (smem[0] + smem[1]) * (1.0f / (float)group_sz);
    }
    __syncthreads();
    float mean = smem[2];

    // 3. Variance: two-warp reduction
    float diff = pre_norm - mean;
    float var_sum = warp_reduce_sum(diff * diff);
    if (lane_id == 0) smem[warp_id] = var_sum;
    __syncthreads();

    if (tid == 0) {
        float var = (smem[0] + smem[1]) * (1.0f / (float)group_sz);
        smem[3] = rsqrtf(var + eps);
    }
    __syncthreads();
    float inv_std = smem[3];

    // 4. Apply GroupNorm affine and store
    output[sample * C + chan] = gamma[chan] * (pre_norm - mean) * inv_std + beta[chan];
}

torch::Tensor fused_swish_bias_groupnorm(
    torch::Tensor input,
    torch::Tensor bias,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups,
    float eps
) {
    const int N = input.size(0);
    const int C = input.size(1);
    const int group_sz = C / num_groups;

    auto output = torch::empty_like(input);

    dim3 grid(N, num_groups);
    dim3 block(group_sz);

    fused_swish_bias_groupnorm_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, eps
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that performs a matrix multiplication, applies Swish activation, sums with a bias term, and normalizes with GroupNorm.
        """
    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.matmul = nn.Linear(in_features, out_features)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.group_norm = nn.GroupNorm(num_groups, out_features)
        # <<<END_IMPROVE>>>

