# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffffu, val, offset);
    return val;
}

// Warp-specialized kernel: one warp (32 threads) per (sample, group).
// Each lane tid processes two channels: group*64+tid and group*64+tid+32.
// Pure warp-shuffle reductions: no shared memory, no __syncthreads.
__global__ void __launch_bounds__(32, 8) fused_swish_bias_groupnorm_kernel_warp32(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int N, int C, float eps
) {
    const int sample= blockIdx.x;
    const int group     = blockIdx.y;
    const int tid       = threadIdx.x;// 0..31
    const int base_chan = group * 64;
    const int chan0     = base_chan + tid;
    const int chan1     = base_chan + tid + 32;

    // Load, apply Swish (x * sigmoid(x)), add per-channel bias
    float r0 = input[sample * C + chan0];
    float r1 = input[sample * C + chan1];
    float v0 = r0 * (1.0f / (1.0f + __expf(-r0))) + bias[chan0];
    float v1 = r1 * (1.0f / (1.0f + __expf(-r1))) + bias[chan1];

    // Single-pass reduction: each lane contributes sum and sumsq for its two channels
    float local_sum   = v0 + v1;
    float local_sumsq = v0 * v0 + v1 * v1;

    float total_sum   = warp_reduce_sum(local_sum);
    float total_sumsq = warp_reduce_sum(local_sumsq);

    // Lane 0 computes mean and inv_std; broadcast to all lanes via shfl
    float mean =0.0f, inv_std = 0.0f;
    if (tid == 0) {
        mean          = total_sum * (1.0f / 64.0f);
        float var     = total_sumsq * (1.0f / 64.0f) - mean * mean;
        inv_std       = rsqrtf(var + eps);
    }
    mean    = __shfl_sync(0xffffffffu, mean,    0);
    inv_std = __shfl_sync(0xffffffffu, inv_std, 0);

    // Apply GroupNorm affine and store both channels
    output[sample * C + chan0] = gamma[chan0] * (v0 - mean) * inv_std + beta[chan0];
    output[sample * C + chan1] = gamma[chan1] * (v1 - mean) * inv_std + beta[chan1];
}

