    float w_sumsq = warp_reduce_sum(pre_norm * pre_norm);
    if (lane_id == 0) {
        smem[warp_id]     = w_sum;
        smem[warp_id + 2] = w_sumsq;
    }
    __syncthreads();

    if (tid == 0) {
        float total_sum   = smem[0] + smem[1];
        float total_sumsq = smem[2] + smem[3];
        float mean = total_sum * (1.0f / (float)group_sz);
        float var  = total_sumsq * (1.0f / (float)group_sz) - mean * mean;
        smem[0] = mean;
        smem[1] = rsqrtf(var + eps);
    }
    __syncthreads();

    float mean    = smem[0];
    float inv_std = smem[1];

